import { sql } from 'drizzle-orm';
import { bigint, integer, timestamp, uuid } from 'drizzle-orm/pg-core';
import { newId } from '@oms/shared';

/**
 * Conventions (see docs/database/DATABASE.md)
 *  - tables: snake_case, plural.   columns: snake_case.   FKs: <entity>_id.
 *  - PK: `id uuid` (UUIDv7 generated by the app; DB default gen_random_uuid() as a safety net).
 *  - every tenant-owned table has `vendor_id uuid not null` as its FIRST column after `id`.
 *  - timestamps are timestamptz, UTC. created_at / updated_at on every mutable table.
 *  - soft delete (`deleted_at`) only on user-managed master data; transactional/log tables are never deleted.
 *  - money: integer minor units (paise) in `*_minor bigint` + `currency char(3)`. Never floats.
 *  - status columns: text + CHECK constraint (cheaper to evolve than pg enums).
 *  - external ids: `external_*` text columns, unique per (marketplace_account_id, external id).
 */
export const pk = () => uuid('id').primaryKey().$defaultFn(newId).default(sql`gen_random_uuid()`);

export const tenantId = () => uuid('vendor_id').notNull();

export const createdAt = () => timestamp('created_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow();
export const updatedAt = () => timestamp('updated_at', { withTimezone: true, mode: 'date' }).notNull().defaultNow().$onUpdate(() => new Date());
export const deletedAt = () => timestamp('deleted_at', { withTimezone: true, mode: 'date' });
export const tz = (name: string) => timestamp(name, { withTimezone: true, mode: 'date' });

export const timestamps = () => ({ createdAt: createdAt(), updatedAt: updatedAt() });

/** optimistic concurrency token, incremented on every update (WHERE version = :expected) */
export const version = () => integer('version').notNull().default(1);

export const minor = (name: string) => bigint(name, { mode: 'number' });

export const inList = (col: string, values: readonly string[]) =>
  sql.raw(`${col} IN (${values.map((v) => `'${v}'`).join(', ')})`);
